function run_all_matlab_reference_tests()
%RUN_ALL_MATLAB_REFERENCE_TESTS Evaluate the unmodified MATLAB benchmarks.
%
% Run from any directory:
%   run('/path/to/validation/matlab/run_all_matlab_reference_tests.m')
%   run_all_matlab_reference_tests
%
% Inputs must first be generated by validation/generate_reference_inputs.py.

script_dir = fileparts(mfilename('fullpath'));
validation_dir = fileparts(script_dir);
python_repo = fileparts(validation_dir);
project_root = fileparts(python_repo);
zhao_repo = fullfile(project_root, '2026ZhaoNash-main');
opt_repo = fullfile(project_root, 'OptMPNDS-master');
input_dir = fullfile(validation_dir, 'test_inputs');
output_dir = fullfile(validation_dir, 'matlab', 'results');
metadata_dir = fullfile(output_dir, 'metadata');

assert(isfolder(zhao_repo), 'Missing MATLAB repository: %s', zhao_repo);
assert(isfolder(opt_repo), 'Missing MATLAB repository: %s', opt_repo);
assert(isfolder(input_dir), ...
    'Missing shared inputs. Run validation/generate_reference_inputs.py first.');
if ~isfolder(output_dir); mkdir(output_dir); end
if ~isfolder(metadata_dir); mkdir(metadata_dir); end

% PROBLEM/GLOBAL are supplied by OptMPNDS.  Benchmark classes and helpers
% are taken from the Zhao repository and deliberately placed first.
addpath(fullfile(opt_repo, 'Public'));
addpath(fullfile(zhao_repo, 'MPMOP'), '-begin');
addpath(fullfile(zhao_repo, 'MPDMP'), '-begin');

problems = [arrayfun(@(i) sprintf('MPMOP%d', i), 1:17, ...
            'UniformOutput', false), ...
            arrayfun(@(i) sprintf('MPDMP%d', i), 1:18, ...
            'UniformOutput', false)];

failures = {};
for k = 1:numel(problems)
    name = problems{k};
    try
        input_table = readtable(fullfile(input_dir, [name '.csv']));
        test_ids = input_table{:, 1};
        X = table2array(input_table(:, 2:end));

        % This is the repository's actual architecture: GLOBAL establishes
        % the singleton consumed by the PROBLEM constructor.
        global_obj = GLOBAL('-problem', str2func(name), '-D', size(X, 2)); %#ok<NASGU>
        problem = feval(name);

        if startsWith(name, 'MPMOP')
            % The supplied MPMOP CalObj methods invoke PopDec().  A
            % zero-argument function handle satisfies that source API
            % without modifying the benchmark.
            pop_dec = @() X;
            F = problem.CalObj(pop_dec);
        else
            F = problem.CalObj(X);
        end

        x_names = arrayfun(@(i) sprintf('x%d', i), 1:size(X, 2), ...
            'UniformOutput', false);
        f_names = arrayfun(@(i) sprintf('f%d', i), 1:size(F, 2), ...
            'UniformOutput', false);
        result = [table(test_ids, 'VariableNames', {'test_id'}), ...
            array2table(X, 'VariableNames', x_names), ...
            array2table(F, 'VariableNames', f_names)];
        writetable(result, fullfile(output_dir, [name '.csv']));

        metadata = capture_metadata(name, problem);
        metadata_file = fullfile(metadata_dir, [name '.json']);
        fid = fopen(metadata_file, 'w');
        assert(fid >= 0, 'Could not open %s', metadata_file);
        cleaner = onCleanup(@() fclose(fid));
        fprintf(fid, '%s\n', jsonencode(metadata));
        clear cleaner;
        fprintf('PASS %s (%d points, %d objectives)\n', name, size(X, 1), size(F, 2));
    catch err
        failures{end + 1, 1} = name; %#ok<AGROW>
        failures{end, 2} = getReport(err, 'extended', 'hyperlinks', 'off');
        fprintf(2, 'FAIL %s: %s\n', name, err.message);
    end
end

if ~isempty(failures)
    failure_file = fullfile(output_dir, 'failures.txt');
    fid = fopen(failure_file, 'w');
    for i = 1:size(failures, 1)
        fprintf(fid, '===== %s =====\n%s\n\n', failures{i, 1}, failures{i, 2});
    end
    fclose(fid);
    error('%d MATLAB benchmark(s) failed. See %s', size(failures, 1), failure_file);
end
fprintf('All %d MATLAB reference evaluations completed.\n', numel(problems));
end


function metadata = capture_metadata(name, problem)
g = problem.Global;
metadata = struct();
metadata.problem = name;
metadata.D = g.D;
metadata.M = g.M;
metadata.encoding = g.encoding;
metadata.lower = g.lower;
metadata.upper = g.upper;

if iscell(g.DM)
    metadata.DM = numel(g.DM);
    groups = cell(1, numel(g.DM));
    for i = 1:numel(g.DM)
        groups{i} = g.DM{i};
    end
else
    metadata.DM = g.DM;
    width = g.M / g.DM;
    groups = cell(1, g.DM);
    for i = 1:g.DM
        groups{i} = ((i - 1) * width + 1):(i * width);
    end
end
metadata.dm_objective_indices_1based = groups;
metadata.matlab_class = class(problem);
metadata.reference_repository = '2026ZhaoNash-main';
end
